<template><main class="admin-content"><NuxtLink to="/admin/accounting" class="text-sm font-bold text-blue-600">← Accounting</NuxtLink><h1 class="mt-2 text-3xl font-black">Chart of Accounts</h1><div class="mt-5 grid gap-5 lg:grid-cols-[1fr_360px]"><section class="admin-panel overflow-hidden"><table class="w-full text-sm"><thead><tr class="bg-slate-50 text-left"><th class="p-3">Code</th><th>Name</th><th>Type</th><th>Normal</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id" class="border-t"><td class="p-3 font-mono">{{a.code}}</td><td><b>{{a.name}}</b><div class="text-xs text-slate-500">{{a.description}}</div></td><td class="capitalize">{{a.account_type}}</td><td class="capitalize">{{a.normal_balance}}</td></tr></tbody></table></section><section class="admin-panel p-5"><h2 class="text-xl font-black">Add Account</h2><label class="block mt-4"><span class="label">Code</span><input v-model="f.code" class="input"></label><label class="block mt-3"><span class="label">Name</span><input v-model="f.name" class="input"></label><label class="block mt-3"><span class="label">Type</span><select v-model="f.account_type" class="input"><option v-for="x in types" :value="x">{{x}}</option></select></label><label class="block mt-3"><span class="label">Description</span><textarea v-model="f.description" class="input"></textarea></label><button class="btn-primary mt-4" @click="add">Add Account</button><p v-if="msg" class="mt-3 text-sm font-bold">{{msg}}</p></section></div></main></template><script setup lang="ts">definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch}=useAdminFetch();const accounts=ref<any[]>([]),types=["asset","liability","equity","revenue","expense"],f=reactive({code:"",name:"",account_type:"expense",description:""}),msg=ref("");async function load(){accounts.value=await adminFetch("/api/admin/accounting/accounts")}async function add(){msg.value="";try{await adminFetch("/api/admin/accounting/accounts",{method:"POST",body:f});Object.assign(f,{code:"",name:"",account_type:"expense",description:""});msg.value="Account added.";await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script><style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.input{@apply w-full rounded-lg border border-slate-300 px-3 py-2}.label{@apply mb-1 block text-sm font-bold}.btn-primary{@apply rounded-lg bg-blue-600 px-5 py-2.5 font-bold text-white}</style>